package main

import (
	"math"
	"testing"
)

// The fit recovers κ and ω0 from points generated by the torque law. The
// points are synthetic: this tests the fitting code, not a bearing.
func TestFitRecovers(t *testing.T) {
	const kappa, w0 = 3.3e-6, 42.0
	var tp []TorquePoint
	var ep []EMFPoint
	for _, i := range []float64{40, 60, 80, 100} {
		for _, w := range []float64{10, 30, 60, 120, 250} {
			tp = append(tp, TorquePoint{i, w, kappa * i * i * math.Tanh(w/w0)})
			ep = append(ep, EMFPoint{i, w, kappa * math.Tanh(w/w0) * w * i})
		}
	}
	for name, f := range map[string]func() (float64, float64, float64, error){
		"torque": func() (float64, float64, float64, error) { return FitTorque(tp) },
		"emf":    func() (float64, float64, float64, error) { return FitBackEMF(ep) },
	} {
		k, w, _, err := f()
		if err != nil {
			t.Fatal(err)
		}
		if math.Abs(k/kappa-1) > 1e-6 || math.Abs(w/w0-1) > 1e-6 {
			t.Errorf("%s fit: κ = %g, ω0 = %g; want %g, %g", name, k, w, kappa, w0)
		}
	}
	if _, _, _, err := FitTorque(tp[:2]); err == nil {
		t.Error("fit with two points must fail")
	}
}

// No measured status is attached to an invented number: every record has
// a source, and no dataset is present without one.
func TestRegistry(t *testing.T) {
	for _, r := range Registry {
		if r.Source == "" || r.Quantity == "" {
			t.Errorf("record without source: %+v", r)
		}
	}
	for _, d := range Datasets {
		if d.Source == "" {
			t.Error("dataset without source")
		}
	}
}

// SPG: the bearing torque needed, its back-EMF in EM mode (which leaves the
// ledger's 1.37 V bound), the thermal mode excluded at the measured η, and
// the engine run independent of the unknown contact resistance in the
// sense that the load never gets more than (E0 − back-EMF)·I.
func TestSPG(t *testing.T) {
	c := CheckSPG(0.10)
	if math.Abs(c.TBearing-24.8) > 0.1 || math.Abs(c.KappaPsi-2.1e-6) > 0.01e-6 {
		t.Errorf("bearing torque %.2f N·m, κψ %.3g", c.TBearing, c.KappaPsi)
	}
	if math.Abs(c.E0-c.BackEMF-1.37) > 0.01 {
		t.Errorf("EMF left %.3f V, ledger bound 1.37 V", c.E0-c.BackEMF)
	}
	if c.VThermal <= c.E0 {
		t.Errorf("thermal mode needs %.2f V, machine makes %.2f V", c.VThermal, c.E0)
	}
	for _, rb := range []float64{1e-6, 1e-5, 1e-4} {
		pl, ps, res, err := SimulateSPGLoop(c, rb)
		if err != nil {
			t.Fatal(err)
		}
		if pl > c.PLoadEM*(1+1e-9) || math.Abs(ps-c.PBearing) > 1e-6*c.PBearing || res > 1e-9 {
			t.Errorf("Rb %g: load %g (≤ %g), shaft %g (want %g), residual %g", rb, pl, c.PLoadEM, ps, c.PBearing, res)
		}
	}
}
